package com.nexodb.ui;

import com.nexodb.tools.SqlProjectService;
import javax.swing.*;
import javax.swing.border.*;
import javax.swing.text.*;
import java.awt.*;
import java.time.*;
import java.time.format.*;
import java.util.*;
import java.util.List;

/** Structured Git history with a colored branch graph, relative dates and commit details. */
final class GitHistoryPanel extends JPanel {
    @FunctionalInterface interface DetailsLoader{String load(String hash)throws Exception;}
    @FunctionalInterface interface ChangesLoader{List<SqlProjectService.GitFileChange> load(String hash)throws Exception;}
    @FunctionalInterface interface PatchLoader{String load(String hash,String path)throws Exception;}
    @FunctionalInterface interface ContentLoader{String load(String hash,String path)throws Exception;}
    private static final int GRAPH_WIDTH=150,DATE_WIDTH=115,AUTHOR_WIDTH=170,REFS_WIDTH=230;
    private static final int[] LIGHT={0x16A36A,0x2589D8,0xE05260,0x7C59C7,0xD38B20,0x0C91A6,0xD04A91,0x5667D8};
    private static final int[] DARK={0x45D99A,0x58B7F2,0xFA7B86,0xB994F4,0xF1B852,0x4ECBDD,0xEE83BE,0x8E9CF2};
    private final DefaultListModel<SqlProjectService.GitGraphLine> model=new DefaultListModel<>();
    private final JList<SqlProjectService.GitGraphLine> list=new JList<>(model);
    private final DefaultListModel<SqlProjectService.GitFileChange> fileModel=new DefaultListModel<>();
    private final JList<SqlProjectService.GitFileChange> files=new JList<>(fileModel);
    private final JTextArea details=new JTextArea(),lineNumbers=new JTextArea();private final DiffPane patch=new DiffPane();private final JLabel summary=new JLabel(" "),scope=new JLabel("Historial completo del proyecto");
    private final JToggleButton changesButton=new JToggleButton("Cambios"),fileButton=new JToggleButton("Archivo completo");private final TitledBorder contentBorder=new TitledBorder("Diferencias del archivo");
    private final DetailsLoader detailsLoader;private final ChangesLoader changesLoader;private final PatchLoader patchLoader;private final ContentLoader contentLoader;private String selectedHash="",focusPath="";private boolean fullFile;

    GitHistoryPanel(DetailsLoader detailsLoader,ChangesLoader changesLoader,PatchLoader patchLoader,ContentLoader contentLoader){
        super(new BorderLayout());this.detailsLoader=detailsLoader;this.changesLoader=changesLoader;this.patchLoader=patchLoader;this.contentLoader=contentLoader;list.setCellRenderer(new HistoryRenderer());list.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);list.setVisibleRowCount(10);list.addListSelectionListener(e->{if(!e.getValueIsAdjusting())loadDetails(list.getSelectedValue());});
        scope.setFont(scope.getFont().deriveFont(Font.BOLD));scope.setBorder(new EmptyBorder(6,8,6,8));JPanel timeline=new JPanel(new BorderLayout());timeline.add(scope,BorderLayout.NORTH);JPanel rows=new JPanel(new BorderLayout());rows.add(new HistoryHeader(),BorderLayout.NORTH);JScrollPane scroll=new JScrollPane(list);scroll.setBorder(BorderFactory.createEmptyBorder());rows.add(scroll);timeline.add(rows);
        details.setEditable(false);details.setFont(new Font(Font.MONOSPACED,Font.PLAIN,12));details.setRows(5);details.setLineWrap(false);details.setText("Selecciona un commit para ver sus archivos y estadísticas.");
        files.setCellRenderer(new FileRenderer());files.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);files.addListSelectionListener(e->{if(!e.getValueIsAdjusting())loadSelectedContent();});JScrollPane fileScroll=new JScrollPane(files);fileScroll.setPreferredSize(new Dimension(310,220));fileScroll.setBorder(new TitledBorder("Archivos modificados"));JScrollPane patchScroll=new JScrollPane(patch);patchScroll.setBorder(contentBorder);lineNumbers.setEditable(false);lineNumbers.setFocusable(false);lineNumbers.setFont(new Font(Font.MONOSPACED,Font.PLAIN,12));lineNumbers.setBackground(ThemeManager.color(0xF2F4F7,0x262B31));lineNumbers.setForeground(ThemeManager.color(0x687482,0x9BA7B4));lineNumbers.setBorder(new EmptyBorder(0,6,0,6));patchScroll.setRowHeaderView(lineNumbers);changesButton.setSelected(true);ButtonGroup modes=new ButtonGroup();modes.add(changesButton);modes.add(fileButton);changesButton.addActionListener(e->{fullFile=false;loadSelectedContent();});fileButton.addActionListener(e->{fullFile=true;loadSelectedContent();});JButton copy=new JButton("Copiar");copy.addActionListener(e->{patch.selectAll();patch.copy();patch.setCaretPosition(0);});JPanel viewActions=new JPanel(new FlowLayout(FlowLayout.LEFT,4,2));viewActions.add(changesButton);viewActions.add(fileButton);viewActions.add(copy);JPanel content=new JPanel(new BorderLayout());content.add(viewActions,BorderLayout.NORTH);content.add(patchScroll);JSplitPane changed=new JSplitPane(JSplitPane.HORIZONTAL_SPLIT,fileScroll,content);changed.setResizeWeight(.24);changed.setDividerLocation(310);
        JPanel commit=new JPanel(new BorderLayout(4,4));summary.setBorder(new EmptyBorder(4,8,2,8));commit.add(summary,BorderLayout.NORTH);JSplitPane info=new JSplitPane(JSplitPane.VERTICAL_SPLIT,new JScrollPane(details),changed);info.setResizeWeight(.23);info.setDividerLocation(115);commit.add(info);
        JSplitPane split=new JSplitPane(JSplitPane.VERTICAL_SPLIT,timeline,commit);split.setResizeWeight(.53);split.setDividerLocation(330);add(split);
    }
    void setScope(String value){scope.setText(value==null||value.isBlank()?"Historial Git":value);}
    void setFocusPath(String value){focusPath=Objects.toString(value,"").replace('\\','/');}
    void setHistory(List<SqlProjectService.GitGraphLine> lines){model.clear();fileModel.clear();patch.showText("");lineNumbers.setText("");summary.setText(" ");for(SqlProjectService.GitGraphLine line:lines)model.addElement(line);details.setText(lines.isEmpty()?"Todavía no hay commits.":"Selecciona un commit para ver sus archivos y estadísticas.");if(!lines.isEmpty()){for(int i=0;i<lines.size();i++)if(lines.get(i).commit()!=null){list.setSelectedIndex(i);break;}}}
    int historySize(){return model.size();}
    int changeCount(){return fileModel.size();}
    String patchText(){return patch.getText();}
    private record CommitView(String details,List<SqlProjectService.GitFileChange> changes){}
    private void loadDetails(SqlProjectService.GitGraphLine line){if(line==null||line.commit()==null)return;String hash=line.commit().hash();selectedHash=hash;details.setText("Leyendo commit "+line.commit().shortHash()+"…");summary.setText("Leyendo archivos modificados…");fileModel.clear();showContent("");new SwingWorker<CommitView,Void>(){protected CommitView doInBackground()throws Exception{return new CommitView(detailsLoader.load(hash),changesLoader.load(hash));}protected void done(){try{if(!hash.equals(selectedHash))return;CommitView value=get();details.setText(value.details());details.setCaretPosition(0);long added=value.changes().stream().mapToLong(SqlProjectService.GitFileChange::additions).sum(),deleted=value.changes().stream().mapToLong(SqlProjectService.GitFileChange::deletions).sum();summary.setText(value.changes().size()+" archivos cambiados     +"+added+"     -"+deleted);for(SqlProjectService.GitFileChange change:value.changes())fileModel.addElement(change);int selected=0;for(int i=0;i<fileModel.size();i++)if(fileModel.get(i).path().replace('\\','/').equals(focusPath)){selected=i;break;}if(!fileModel.isEmpty())files.setSelectedIndex(selected);else showContent("Este commit no contiene cambios de archivos visibles.");}catch(Exception error){details.setText("No se pudo leer el commit: "+root(error).getMessage());summary.setText("No se pudo cargar el detalle.");}}}.execute();}
    void showFullFile(){fullFile=true;fileButton.setSelected(true);loadSelectedContent();}
    private void loadSelectedContent(){SqlProjectService.GitFileChange change=files.getSelectedValue();if(change==null||selectedHash.isBlank())return;String hash=selectedHash,path=change.path();boolean complete=fullFile;showContent("Leyendo "+(complete?"archivo completo ":"diferencias de ")+path+"…");new SwingWorker<String,Void>(){protected String doInBackground()throws Exception{return complete?contentLoader.load(hash,path):patchLoader.load(hash,path);}protected void done(){try{SqlProjectService.GitFileChange selected=files.getSelectedValue();if(hash.equals(selectedHash)&&selected!=null&&path.equals(selected.path())&&complete==fullFile)showContent(get());}catch(Exception error){showContent("No se pudo leer "+(complete?"el archivo":"la diferencia")+": "+root(error).getMessage());}}}.execute();}
    private void showContent(String value){patch.showText(value);contentBorder.setTitle(fullFile?"Archivo completo en esta versión":"Diferencias del archivo");lineNumbers.setText(fullFile?lineNumbers(value):"");repaint();}
    private static String lineNumbers(String value){int lines=Math.max(1,Objects.toString(value,"").split("\\R",-1).length);StringBuilder result=new StringBuilder();for(int i=1;i<=lines;i++)result.append(i).append('\n');return result.toString();}
    private static Throwable root(Throwable value){Throwable result=value;while(result.getCause()!=null&&result.getCause()!=result)result=result.getCause();return result;}
    private static Color lane(int index){int slot=Math.floorMod(index,LIGHT.length);return ThemeManager.color(LIGHT[slot],DARK[slot]);}
    private static String html(String value){return value==null?"":value.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
    static String relativeDate(String value,Instant now){
        try{Instant date=OffsetDateTime.parse(value).toInstant();long seconds=Duration.between(date,now).getSeconds();if(seconds<0)return exactDate(date);if(seconds<60)return "ahora";if(seconds<3600)return "hace "+seconds/60+" min";if(seconds<86_400)return "hace "+seconds/3600+" h";if(seconds<604_800)return "hace "+seconds/86_400+(seconds/86_400==1?" día":" días");return exactDate(date);}catch(Exception ignored){return value;}
    }
    private static String exactDate(Instant value){return DateTimeFormatter.ofPattern("dd MMM yyyy",new Locale("es","ES")).withZone(ZoneId.systemDefault()).format(value);}

    private static final class FileRenderer extends JPanel implements ListCellRenderer<SqlProjectService.GitFileChange>{
        private final JLabel state=new JLabel(),path=new JLabel(),stats=new JLabel();FileRenderer(){super(new BorderLayout(7,0));setBorder(new CompoundBorder(new MatteBorder(0,0,1,0,ThemeManager.color(0xE2E7ED,0x4B535C)),new EmptyBorder(7,8,7,8)));state.setHorizontalAlignment(SwingConstants.CENTER);state.setPreferredSize(new Dimension(25,24));state.setOpaque(true);state.setForeground(Color.WHITE);state.setFont(state.getFont().deriveFont(Font.BOLD));stats.setFont(new Font(Font.MONOSPACED,Font.PLAIN,11));add(state,BorderLayout.WEST);add(path);add(stats,BorderLayout.EAST);}
        public Component getListCellRendererComponent(JList<? extends SqlProjectService.GitFileChange> source,SqlProjectService.GitFileChange value,int index,boolean selected,boolean focus){String code=value.status().isBlank()?"M":value.status().substring(0,1);state.setText(code);state.setBackground(switch(code){case "A"->ThemeManager.color(0x16864B,0x2EB872);case "D"->ThemeManager.color(0xC43D4B,0xE75A67);case "R"->ThemeManager.color(0x7C59C7,0xA985E8);default->ThemeManager.color(0x287BC1,0x4FA4E8);});path.setText(value.path());path.setToolTipText(value.path());stats.setText("+"+value.additions()+"  -"+value.deletions());stats.setForeground(ThemeManager.color(0x53606D,0xB9C3CF));setBackground(selected?source.getSelectionBackground():source.getBackground());path.setForeground(selected?source.getSelectionForeground():source.getForeground());return this;}
    }
    private static final class DiffPane extends JTextPane{
        DiffPane(){setEditable(false);setFont(new Font(Font.MONOSPACED,Font.PLAIN,12));}
        void showText(String text){StyledDocument document=getStyledDocument();try{document.remove(0,document.getLength());String value=Objects.toString(text,"");for(String line:value.split("(?<=\\n)",-1)){SimpleAttributeSet style=new SimpleAttributeSet();if(line.startsWith("+")&&!line.startsWith("+++")){StyleConstants.setForeground(style,ThemeManager.color(0x116B38,0x71DB9B));StyleConstants.setBackground(style,ThemeManager.color(0xE6F5EA,0x173D2B));}else if(line.startsWith("-")&&!line.startsWith("---")){StyleConstants.setForeground(style,ThemeManager.color(0xA92736,0xFF8C96));StyleConstants.setBackground(style,ThemeManager.color(0xFBEAEC,0x45232A));}else if(line.startsWith("@@")){StyleConstants.setForeground(style,ThemeManager.color(0x245DA8,0x80B9FF));StyleConstants.setBackground(style,ThemeManager.color(0xE9F1FC,0x20364E));StyleConstants.setBold(style,true);}else if(line.startsWith("diff --git")||line.startsWith("index ")||line.startsWith("---")||line.startsWith("+++")){StyleConstants.setForeground(style,ThemeManager.color(0x4B5563,0xB9C3CF));StyleConstants.setBold(style,true);}document.insertString(document.getLength(),line,style);}setCaretPosition(0);}catch(BadLocationException ignored){setText(text);}}
    }

    private static final class HistoryHeader extends JPanel{
        HistoryHeader(){super(new BorderLayout());setBorder(new CompoundBorder(new MatteBorder(0,0,1,0,ThemeManager.color(0xD8DEE6,0x59616B)),new EmptyBorder(8,8,8,8)));JLabel graph=header("Ramas",GRAPH_WIDTH),date=header("Fecha",DATE_WIDTH),author=header("Autor",AUTHOR_WIDTH),message=header("Mensaje",0),refs=header("Ramas y etiquetas",REFS_WIDTH);add(graph,BorderLayout.WEST);JPanel columns=new JPanel(new BorderLayout());columns.setOpaque(false);columns.add(date,BorderLayout.WEST);JPanel center=new JPanel(new BorderLayout());center.setOpaque(false);center.add(author,BorderLayout.WEST);center.add(message);center.add(refs,BorderLayout.EAST);columns.add(center);add(columns);}
        private static JLabel header(String text,int width){JLabel label=new JLabel(text);label.setFont(label.getFont().deriveFont(Font.BOLD));if(width>0){Dimension size=new Dimension(width,22);label.setPreferredSize(size);label.setMinimumSize(size);}return label;}
    }

    private final class HistoryRenderer extends JPanel implements ListCellRenderer<SqlProjectService.GitGraphLine>{
        private final Graph graph=new Graph();private final JLabel date=new JLabel(),author=new JLabel(),message=new JLabel();private final RefBadges refs=new RefBadges();
        HistoryRenderer(){super(new BorderLayout());setBorder(new CompoundBorder(new MatteBorder(0,0,1,0,ThemeManager.color(0xE2E7ED,0x4B535C)),new EmptyBorder(4,8,4,8)));graph.setPreferredSize(new Dimension(GRAPH_WIDTH,46));date.setPreferredSize(new Dimension(DATE_WIDTH,46));author.setPreferredSize(new Dimension(AUTHOR_WIDTH,46));author.setIconTextGap(8);refs.setPreferredSize(new Dimension(REFS_WIDTH,46));add(graph,BorderLayout.WEST);JPanel columns=new JPanel(new BorderLayout());columns.setOpaque(false);columns.add(date,BorderLayout.WEST);JPanel center=new JPanel(new BorderLayout());center.setOpaque(false);center.add(author,BorderLayout.WEST);center.add(message);center.add(refs,BorderLayout.EAST);columns.add(center);add(columns);}
        public Component getListCellRendererComponent(JList<? extends SqlProjectService.GitGraphLine> source,SqlProjectService.GitGraphLine item,int index,boolean selected,boolean focus){graph.value=item;SqlProjectService.GitCommit commit=item.commit();if(commit==null){date.setText("");author.setText("");author.setIcon(null);message.setText("");refs.value="";}else{date.setText(relativeDate(commit.date(),Instant.now()));date.setToolTipText(commit.date());author.setText("<html>"+html(commit.author())+"</html>");author.setIcon(new AvatarIcon(commit.author()));String merge=commit.parents().size()>1?"<font color='#8B929A'>[M]</font> ":"";message.setText("<html>"+merge+"<b>"+html(commit.subject())+"</b><br><font color='"+(ThemeManager.isDark()?"#B8C1CC":"#67717E")+"'>"+html(commit.shortHash())+"</font></html>");refs.value=commit.refs();}Color background=selected?source.getSelectionBackground():source.getBackground(),foreground=selected?source.getSelectionForeground():source.getForeground();setBackground(background);date.setForeground(foreground);author.setForeground(foreground);message.setForeground(foreground);graph.setBackground(background);refs.setBackground(background);setToolTipText(commit==null?null:commit.hash());return this;}
    }
    private static final class AvatarIcon implements Icon{
        private final String text;private final Color color;AvatarIcon(String author){String[] words=Objects.toString(author,"").trim().split("\\s+");text=words.length==0||words[0].isBlank()?"?":(""+words[0].charAt(0)+(words.length>1?words[words.length-1].charAt(0):' ')).trim().toUpperCase(Locale.ROOT);color=lane(Objects.toString(author,"").hashCode());}
        public int getIconWidth(){return 26;}public int getIconHeight(){return 26;}public void paintIcon(Component c,Graphics graphics,int x,int y){Graphics2D g=(Graphics2D)graphics.create();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setColor(color);g.fillOval(x,y,25,25);g.setColor(Color.WHITE);g.setFont(c.getFont().deriveFont(Font.BOLD,10f));FontMetrics fm=g.getFontMetrics();g.drawString(text,x+(25-fm.stringWidth(text))/2,y+(25-fm.getHeight())/2+fm.getAscent());g.dispose();}
    }
    private static final class RefBadges extends JComponent{
        private String value="";RefBadges(){setOpaque(true);}protected void paintComponent(Graphics graphics){super.paintComponent(graphics);if(value==null||value.isBlank())return;Graphics2D g=(Graphics2D)graphics.create();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setFont(getFont().deriveFont(Font.BOLD,11f));int x=4,y=(getHeight()-23)/2,index=0;String[] tokens=value.split(",\\s*");for(String raw:tokens){String token=raw.replace("HEAD -> ","").replace("tag: ","").trim();if(token.isBlank())continue;if(index==2)token="+"+(tokens.length-index);FontMetrics fm=g.getFontMetrics();int width=Math.min(REFS_WIDTH-x-6,fm.stringWidth(token)+18);if(width<25)break;g.setColor(lane(index+1));g.fillRoundRect(x,y,width,23,12,12);g.setColor(Color.WHITE);String shown=token;while(fm.stringWidth(shown)>width-16&&shown.length()>2)shown=shown.substring(0,shown.length()-2)+"…";g.drawString(shown,x+9,y+16);x+=width+6;index++;if(index>=3||x>=REFS_WIDTH-20)break;}g.dispose();}
    }
    private static final class Graph extends JComponent{
        private SqlProjectService.GitGraphLine value;Graph(){setOpaque(true);}protected void paintComponent(Graphics graphics){super.paintComponent(graphics);if(value==null)return;Graphics2D g=(Graphics2D)graphics.create();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);String text=value.graph();int h=getHeight(),step=10;g.setStroke(new BasicStroke(2.4f,BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));for(int i=0;i<text.length();i++){char ch=text.charAt(i);int x=12+i*step,colorIndex=i/2;g.setColor(lane(colorIndex));switch(ch){case '|':g.drawLine(x,0,x,h);break;case '/':g.drawLine(x+step,0,x,h);break;case '\\':g.drawLine(x,0,x+step,h);break;case '-':case '_':g.drawLine(x-step,h/2,x+step,h/2);break;case '*':g.drawLine(x,0,x,h);g.fillOval(x-5,h/2-5,10,10);g.setColor(getBackground());g.fillOval(x-2,h/2-2,4,4);break;default:break;}}g.dispose();}
    }
}
